import React from 'react';
import { NavLink, Link } from 'react-router-dom';
import logo from "../assets/images/logo.jpeg";
import "./header.css";

export default function Header(){
  const [open, setOpen] = React.useState(false);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
      window.scrollTo(0, 0);
      setIsVisible(true);
    }, []);

  return (
    <header className="header">
      <div className="container header-inner">
        <Link to="/" className="logo">
  <img src={logo} alt="Kilowatt Electric Logo" className="logo-img" />
</Link>
        <nav className="nav" style={{display: open ? 'flex' : undefined, flexDirection: open ? 'column' : undefined}}>
          <NavLink to="/" end>Home</NavLink>
          <NavLink to="/products">Products</NavLink>
          <NavLink to="/services">Services</NavLink>
          <NavLink to="/contact">Contact</NavLink>
        </nav>
        <button className="nav-toggle" aria-label="toggle" onClick={()=>setOpen(!open)}>☰</button>
      </div>
      <section
        id="home"
        className={`hero ${isVisible ? 'visible' : ''}`}>
              <div className="container hero-inner">
                <div className="hero-copy">
                  <h1 className={`fade-in-hero ${isVisible ? 'visible' : ''}`}>
                    Your Space Can Now Listen, Learn and Respond!
                  </h1>
                  <p
                    className={`lead fade-in-hero ${isVisible ? 'visible' : ''}`}
                    style={{ transitionDelay: '200ms' }}
                  >
                    Smart home & building automation solutions that make everyday living intelligent, efficient and secure.
                  </p>
                  <Link
                    className={`btn fade-in-hero ${isVisible ? 'visible' : ''}`}
                    style={{ transitionDelay: '400ms' }}
                    to="/products"
                  >
                    Our Products
                  </Link>
                </div>
              </div>
            </section>
    </header>
  );
}
